import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int rows = (int) nextLong(), cols = (int) nextLong();
        int ir = (int) nextLong(), ic = (int) nextLong(), fr = (int) nextLong(), fc = (int) nextLong();
        long[] cr = new long[rows - 1], cc = new long[cols - 1];
        for (int i = 0; i < rows - 1; i++) cr[i] = nextLong();
        for (int j = 0; j < cols - 1; j++) cc[j] = nextLong();
        // Each row edge and each column edge between start and target is crossed exactly once.
        long total = 0;
        for (int i = Math.min(ir, fr); i < Math.max(ir, fr); i++) total += cr[i];
        for (int j = Math.min(ic, fc); j < Math.max(ic, fc); j++) total += cc[j];
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	rows, cols := int(nextInt()), int(nextInt())
	ir, ic, fr, fc := int(nextInt()), int(nextInt()), int(nextInt()), int(nextInt())
	cr, cc := make([]int64, rows-1), make([]int64, cols-1)
	for i := range cr {
		cr[i] = nextInt()
	}
	for j := range cc {
		cc[j] = nextInt()
	}
	// Each row edge and each column edge between start and target is crossed exactly once.
	total := int64(0)
	for i := min(ir, fr); i < max(ir, fr); i++ {
		total += cr[i]
	}
	for j := min(ic, fc); j < max(ic, fc); j++ {
		total += cc[j]
	}
	fmt.Println(total)
}
